public static OLK_EnvironmentDataSetupCode find(
    OLK_EdsEnvironmentId    _environmentId,
    OLK_EdsDataAreaId       _dataAreaId,
    OLK_EdsClassId          _classId,
    OLK_EdsMethodName       _methodName,
    boolean                 _forUpdate = false)
{
    OLK_EnvironmentDataSetupCode code;

    code.selectForUpdate(_forUpdate);

    select firstonly code
        where code.EnvironmentId == _environmentId
           && code.RefDataAreaId == _dataAreaId
           && code.ClassId       == _classId
           && code.MethodName    == _methodName;

    return code;
}

/// <summary>
/// Gets or sets the code job class by its name.
/// </summary>
/// <param name = "_set">true when the value is set.</param>
/// <param name = "_name">The class name.</param>
/// <returns>The name of the code job class.</returns>
public edit ClassName className(boolean _set, ClassName _name)
{
    if (_set)
    {
        ClassId classId = _name ? className2Id(_name) : 0;

        if (_name && !classId)
        {
            checkFailed(strFmt("@OLK_EDSLabel:ClassNotFound", _name));
        }
        else
        {
            this.ClassId = classId;
        }
    }

    return this.ClassId ? classId2Name(this.ClassId) : '';
}

/// <summary>
/// Creates an inactive code job unless it already exists.
/// </summary>
/// <returns>true if the code job was created; false if it already existed.</returns>
public static boolean createCode(
    OLK_EdsEnvironmentId    _environmentId,
    OLK_EdsDataAreaId       _dataAreaId,
    OLK_EdsClassId          _classId,
    OLK_EdsMethodName       _methodName,
    FreeTxt                 _description)
{
    OLK_EnvironmentDataSetupCode code;

    if (OLK_EnvironmentDataSetupCode::find(_environmentId, _dataAreaId, _classId, _methodName).RecId)
    {
        return false;
    }

    code.EnvironmentId  = _environmentId;
    code.RefDataAreaId  = _dataAreaId;
    code.ClassId        = _classId;
    code.MethodName     = _methodName;
    code.Description    = _description;
    code.Active         = NoYes::No;
    code.insert();

    return true;
}

/// <summary>
/// Activates or deactivates every code job a query selects, as the Activate all and Deactivate all buttons do.
/// </summary>
/// <param name = "_query">A query on code jobs, for example the query of the Code jobs form.</param>
/// <param name = "_active">Yes to activate the code jobs; No to deactivate them.</param>
/// <returns>The number of code jobs that were changed.</returns>
public static int setActiveForQuery(Query _query, OLK_EdsActive _active)
{
    QueryRun                        queryRun = new QueryRun(_query);
    OLK_EnvironmentDataSetupCode    code;
    int                             changed;

    ttsbegin;

    while (queryRun.next())
    {
        code = queryRun.get(tableNum(OLK_EnvironmentDataSetupCode));

        if (code.Active != _active)
        {
            code.selectForUpdate(true);
            code.reread();
            code.Active = _active;
            code.update();
            changed++;
        }
    }

    ttscommit;

    return changed;
}

/// <summary>
/// Deletes every code job a query selects, as the Delete all button does.
/// </summary>
/// <param name = "_query">A query on code jobs, for example the query of the Code jobs form.</param>
/// <returns>The number of code jobs that were deleted.</returns>
public static int deleteForQuery(Query _query)
{
    QueryRun                        queryRun = new QueryRun(_query);
    OLK_EnvironmentDataSetupCode    code;
    int                             deleted;

    ttsbegin;

    while (queryRun.next())
    {
        code = queryRun.get(tableNum(OLK_EnvironmentDataSetupCode));
        code.selectForUpdate(true);
        code.reread();

        if (code.RecId)
        {
            code.delete();
            deleted++;
        }
    }

    ttscommit;

    return deleted;
}

public boolean validateWrite()
{
    boolean ret = super();

    if (ret && !OLK_EnvironmentDataSetupExecuteCode::isCodeJobMethod(this.ClassId, this.MethodName))
    {
        ret = checkFailed(strFmt("@OLK_EDSLabel:NotACodeJob", this.MethodName, classId2Name(this.ClassId)));
    }

    return ret;
}
